// Shared notification pipeline. Channel-specific behavior is supplied by a
// strategy object (see ./channels) and composed in, rather than inherited.

const HOUR_MS = 60 * 60 * 1000;

function validateUser(user) {
  if (!user || typeof user !== 'object') {
    throw new TypeError('user is required');
  }
  if (!user.id) {
    throw new TypeError('user.id is required');
  }
}

function validateMessage(message) {
  if (!message || typeof message !== 'object') {
    throw new TypeError('message is required');
  }
  if (!message.title || !message.body) {
    throw new TypeError('message.title and message.body are required');
  }
}

function applyTemplate(value, user, message) {
  return String(value)
    .replace(/\{\{name\}\}/g, user.name || 'there')
    .replace(/\{\{id\}\}/g, user.id)
    .replace(/\{\{category\}\}/g, message.category || 'general');
}

function createNotifierFromStrategy(strategy, options = {}) {
  const config = {
    channel: strategy.channel,
    transport: options.transport || {},
    templates: options.templates || {},
    throttleStore: options.throttleStore || new Map(),
    now: options.now || (() => new Date()),
    defaultSender: options.defaultSender || 'Product Team',
    defaultLocale: options.defaultLocale || 'en-US',
    maxPerHour: options.maxPerHour || strategy.defaultMaxPerHour,
    ...strategy.configure(options)
  };

  function throttleKey(user, message) {
    const category = message.category || 'general';
    return `${config.channel}:${user.id}:${category}`;
  }

  function baseThrottle(user, message, sendOptions = {}) {
    if (sendOptions.force || message.priority === 'urgent') {
      return { throttled: false };
    }

    const key = throttleKey(user, message);
    const now = config.now().getTime();
    const records = (config.throttleStore.get(key) || []).filter(ts => now - ts < HOUR_MS);

    if (records.length >= config.maxPerHour) {
      return {
        throttled: true,
        reason: `${config.channel} hourly limit reached`,
        retryAt: new Date(records[0] + HOUR_MS).toISOString()
      };
    }

    return { throttled: false };
  }

  function baseFormat(user, message, sendOptions = {}) {
    const id = `${config.channel}-${user.id}-${config.now().getTime()}`;
    const locale = sendOptions.locale || user.locale || config.defaultLocale;
    const title = applyTemplate(message.title, user, message);
    const body = applyTemplate(message.body, user, message);

    return {
      id,
      channel: config.channel,
      locale,
      title,
      body,
      preview: `${title}: ${body}`.slice(0, 120),
      metadata: {
        category: message.category || 'general',
        priority: message.priority || 'normal',
        generatedAt: config.now().toISOString()
      }
    };
  }

  function shouldThrottle(user, message, sendOptions = {}) {
    if (strategy.shouldThrottle) {
      return strategy.shouldThrottle(config, user, message, sendOptions, baseThrottle);
    }
    return baseThrottle(user, message, sendOptions);
  }

  function format(user, message, sendOptions = {}) {
    const formatted = baseFormat(user, message, sendOptions);
    return strategy.format(config, formatted, user, message, sendOptions);
  }

  async function deliver(payload) {
    const send = config.transport[strategy.transportKey];
    if (typeof send !== 'function') {
      throw new Error(strategy.transportMissingMessage);
    }
    await send.call(config.transport, payload);
  }

  function recordDelivery(user, message) {
    const key = throttleKey(user, message);
    const records = config.throttleStore.get(key) || [];
    records.push(config.now().getTime());
    config.throttleStore.set(key, records);
  }

  function checkUser(user) {
    validateUser(user);
    strategy.validateUser(user);
  }

  async function send(user, message, sendOptions = {}) {
    checkUser(user);
    validateMessage(message);

    const throttle = shouldThrottle(user, message, sendOptions);
    if (throttle.throttled) {
      return {
        channel: config.channel,
        status: 'throttled',
        reason: throttle.reason,
        retryAt: throttle.retryAt,
        userId: user.id
      };
    }

    const formatted = format(user, message, sendOptions);
    await deliver(formatted);
    recordDelivery(user, message);

    return {
      channel: config.channel,
      status: 'sent',
      userId: user.id,
      id: formatted.id,
      preview: formatted.preview
    };
  }

  return {
    channel: config.channel,
    config,
    send,
    validateUser: checkUser,
    validateMessage,
    shouldThrottle,
    format,
    applyTemplate
  };
}

module.exports = { createNotifierFromStrategy };
const { createNotifierFromStrategy } = require('./core');
const email = require('./channels/email');
const sms = require('./channels/sms');
const slack = require('./channels/slack');
const inapp = require('./channels/inapp');

const strategies = { email, sms, slack, inapp };

const registry = Object.keys(strategies).reduce((all, channel) => {
  all[channel] = (options = {}) => createNotifierFromStrategy(strategies[channel], options);
  return all;
}, {});

function createNotifier(channel, options = {}) {
  const factory = Object.prototype.hasOwnProperty.call(registry, channel) ? registry[channel] : null;
  if (!factory) {
    throw new TypeError(`unknown notification channel: ${channel}`);
  }
  return factory(options);
}

function createAllNotifiers(options = {}) {
  return Object.keys(registry).reduce((all, channel) => {
    all[channel] = createNotifier(channel, options);
    return all;
  }, {});
}

module.exports = {
  createNotifier,
  createAllNotifiers,
  registry
};
function blocksFor(formatted, mention) {
  return [
    {
      type: 'section',
      text: { type: 'mrkdwn', text: `${mention}*${formatted.title}*` }
    },
    {
      type: 'section',
      text: { type: 'mrkdwn', text: formatted.body }
    },
    {
      type: 'context',
      elements: [{ type: 'mrkdwn', text: `Category: ${formatted.metadata.category}` }]
    }
  ];
}

module.exports = {
  channel: 'slack',
  defaultMaxPerHour: 20,
  transportKey: 'slack',
  transportMissingMessage: 'slack transport is not configured',

  configure(options) {
    return {
      defaultWorkspace: options.defaultWorkspace || 'main',
      defaultChannel: options.defaultChannel || '#general'
    };
  },

  validateUser(user) {
    if (!user.slackId && !user.slackChannel) {
      throw new TypeError('user.slackId or user.slackChannel is required for Slack notifications');
    }
  },

  shouldThrottle(config, user, message, options, baseThrottle) {
    if (options.threadTs) {
      return { throttled: false };
    }
    return baseThrottle(user, message, options);
  },

  format(config, formatted, user, message, options) {
    const channel = options.channel || user.slackChannel || config.defaultChannel;
    const mention = user.slackId ? `<@${user.slackId}> ` : '';
    const text = `${mention}*${formatted.title}*\n${formatted.body}`;

    return {
      ...formatted,
      workspace: user.slackWorkspace || config.defaultWorkspace,
      channel,
      threadTs: options.threadTs || null,
      text,
      blocks: blocksFor(formatted, mention),
      preview: text.replace(/\*/g, '').slice(0, 120)
    };
  }
};
function truncate(config, value) {
  if (value.length <= config.segmentLength) {
    return value;
  }
  return `${value.slice(0, config.segmentLength - 1)}…`;
}

module.exports = {
  channel: 'sms',
  defaultMaxPerHour: 4,
  transportKey: 'sms',
  transportMissingMessage: 'sms transport is not configured',

  configure(options) {
    return {
      senderId: options.senderId || 'APP',
      segmentLength: options.segmentLength || 140
    };
  },

  validateUser(user) {
    if (!user.phone || !/^\+[1-9]\d{6,14}$/.test(user.phone)) {
      throw new TypeError('user.phone must be E.164 for SMS notifications');
    }
  },

  shouldThrottle(config, user, message, options, baseThrottle) {
    const base = baseThrottle(user, message, options);
    if (base.throttled) {
      return base;
    }
    if (message.category === 'marketing' && !user.smsOptIn) {
      return {
        throttled: true,
        reason: 'user has not opted into marketing SMS',
        retryAt: null
      };
    }
    return { throttled: false };
  },

  format(config, formatted, user, message) {
    const prefix = message.priority === 'urgent' ? 'URGENT: ' : '';
    const text = truncate(config, `${prefix}${formatted.title} - ${formatted.body}`);

    return {
      ...formatted,
      to: user.phone,
      from: config.senderId,
      text,
      segments: Math.ceil(text.length / config.segmentLength),
      preview: text
    };
  }
};
